pub fn statements(values: List<Int>) -> Int {
	let mut total: Int = 0
	let current = total
	total = total + 1
	if total > 0 {
		discard current
	} else if total == 0 {
		defer cleanup(total)
	} else {
		return 0
	}
	while total < 10 {
		total = total + 1
		break
	}
	for item in values {
		discard item
		continue
	}
	return total
}

pub fn aggregate(value: Int, y: Int) -> Int {
	let list = [1, value + 1, y,]
	let grouped = (value + 1)
	let tuple = (value, y)
	let point = Point { x: value, y, }
	let called = build<Result<Int>>(point, list,)
	let updated = point with { x: called, y, }
	discard grouped
	discard tuple
	discard updated
	return called
}

pub fn flow(flag: Bool) -> Int {
	let selected = if flag then 1 else 2
	let tasks = parallel {
		one: work(1)
		two: work(2)
	}
	let attempted = parallel try {
		first: work(3)
	}
	discard tasks
	discard attempted
	return selected
}

pub fn classify(value: Result<Int, String>) -> Int {
	return match value {
		Ok(0..=10) | Ok(20) => 1
		Err { message } => 2
		Ok([first, ...rest]) => first
		_ => 0
	}
}

pub fn transform(value: Int) -> Int {
	let mapper = |current: Int| -> Int => current + 1
	return value |> mapper |> finish
}

